<?php require 'includes/db.php'; require 'includes/auth.php'; if(!user_id()){header('Location: login.php');exit;}$s=db()->prepare('SELECT name,email,created_at FROM users WHERE id=?');$s->execute([user_id()]);$u=$s->fetch();require 'includes/header.php';?><div class="form-card"><h1>Account</h1><p><b>Name:</b> <?=e($u['name'])?></p><p><b>Email:</b> <?=e($u['email'])?></p><p><b>Created:</b> <?=e($u['created_at'])?></p><a class="btn secondary" href="logout.php">Log out</a></div><?php require 'includes/footer.php';?>